db.embedded_movies.aggregate( [
   {
      $scoreFusion: {
         input: {
            pipelines: {
               searchOne: [
                  {
                     "$vectorSearch": {
                        "index": "<INDEX_NAME>",
                        "path": "<FIELD_NAME>",
                        "queryVector": <QUERY_EMBEDDINGS>,
                        "numCandidates": <NUMBER_OF_NEAREST_NEIGHBORS_TO_CONSIDER>,
                        "limit": <NUBMER_OF_DOCUMENTS_TO_RETURN>
                     }
                  }
               ],
               searchTwo: [
                  {
                     "$search": {
                        "index": "<INDEX_NAME>",
                        "text": {
                           "query": "<QUERY_TERM>",
                           "path": "<FIELD_NAME>"
                        }
                     }
                  },
               ]
            },
            normalization: "sigmoid"
         },
         combination: {
            method: "expression",
            expression: {
               $sum: [
                 {$multiply: [ "$$searchOne", 10]}, "$$searchTwo"
               ]
            }
         },
         "scoreDetails": true
      }
   },
   {
      "$project": {
         _id: 1,
         title: 1,
         plot: 1,
         scoreDetails: {"$meta": "scoreDetails"}
      }
   },
   { $limit: 20 }
] )

